const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Point([30.40, 31.65]); // A point near the Rosetta branch mouth
  const year1 = 1984;
  const year2 = 2021;
  const startDate = '-06-01'; // June 1st
  const endDate = '-08-31';   // August 31st

  const date1Start = ee.Date(year1 + startDate);
  const date1End = ee.Date(year1 + endDate);
  const date2Start = ee.Date(year2 + startDate);
  const date2End = ee.Date(year2 + endDate);

  // Function to mask clouds and scale surface reflectance bands for Landsat SR collections.
  const maskCloudsAndScale = (image) => {
    const qa = image.select('QA_PIXEL');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));

    // Apply the scaling factor to the surface reflectance bands.
    const opticalBands = image.select('SR_B.*').multiply(0.0000275).add(-0.2);
    // Apply the mask and add the scaled bands.
    return image.addBands(opticalBands, null, true)
                .updateMask(mask)
                .copyProperties(image, ['system:time_start']);
  };

  // Function to calculate NDVI for Landsat images
  const addNDVI = (image) => {
    // Determine band names based on the Landsat mission
    let nir, red;
    if (image.get('SATELLITE').getInfo() === 'LANDSAT_5') {
      nir = 'SR_B4';
      red = 'SR_B3';
    } else { // Assuming Landsat 8/9
      nir = 'SR_B5';
      red = 'SR_B4';
    }
    const ndvi = image.normalizedDifference([nir, red]).rename('NDVI');
    return image.addBands(ndvi);
  };

  // 2. Data Acquisition & Check
  // Landsat 5 for 1984
  let collection1 = ee.ImageCollection('LANDSAT/LT05/C02/T1_SR')
    .filterBounds(geometry)
    .filterDate(date1Start, date1End)
    .map(maskCloudsAndScale)
    .map(addNDVI);

  let size1 = await collection1.size().getInfo();
  if (size1 === 0) {
    console.log(`No images found for ${year1}.`);
    console.log('C1');
    return;
  }
  let image1 = collection1.median();

  // Landsat 8 for 2021
  let collection2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
    .filterBounds(geometry)
    .filterDate(date2Start, date22End)
    .map(maskCloudsAndScale)
    .map(addNDVI);

  let size2 = await collection2.size().getInfo();
  if (size2 === 0) {
    console.log(`No images found for ${year2}.`);
    console.log('C1');
    return;
  }
  let image2 = collection2.median();

  // 3. Processing & Calculation
  const scale = 30; // Landsat resolution
  const reducer = ee.Reducer.mean();
  const maxPixels = 1e9;

  // Calculate mean NDVI for 1984
  const ndvi1_obj = await image1.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDVI');

  const ndvi1 = ndvi1_obj.getInfo();

  // Count valid pixels for 1984
  const count1_obj = await image1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDVI');

  const count1 = count1_obj.getInfo();

  if (count1 === 0) {
    console.log(`No valid pixels remaining for ${year1} after masking.`);
    console.log('C2');
    return;
  }

  // Calculate mean NDVI for 2021
  const ndvi2_obj = await image2.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDVI');

  const ndvi2 = ndvi2_obj.getInfo();

  // Count valid pixels for 2021
  const count2_obj = await image2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDVI');

  const count2 = count2_obj.getInfo();

  if (count2 === 0) {
    console.log(`No valid pixels remaining for ${year2} after masking.`);
    console.log('C2');
    return;
  }

  // 4. Validation & Final Answer
  if (ndvi1 === null || isNaN(ndvi1) || ndvi2 === null || isNaN(ndvi2)) {
    console.log('NDVI calculation failed (null/NaN result).');
    console.log('C3');
    return;
  }

  console.log(`Images ${year1}: ${size1} (Valid Pixels: ${count1})`);
  console.log(`Images ${year2}: ${size2} (Valid Pixels: ${count2})`);
  console.log(`Average NDVI ${year1}: ${ndvi1.toFixed(3)}`);
  console.log(`Average NDVI ${year2}: ${ndvi2.toFixed(3)}`);

  if (ndvi1 > ndvi2) {
    console.log('A'); // Yes, vegetation cover was greater in 1984.
  } else {
    console.log('B'); // No, vegetation cover was not greater in 1984.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
